  if(!marker||!unit||unit.id!==unitId||unit.owner!=='soviet'||unit.marker===true||unit.hex!==marker.hex||
     !controlled(state,unit.hex))throw Error('Ground unit must share a Soviet-controlled port with the Fleet');
